{"id":"Tricep_Dumbbell_Kickback","name":"哑铃俯身臂屈伸","en":"Tricep Dumbbell Kickback","cats":["tri"],"eq":["dumbbell"],"pe":"dumbbell","lv":"beginner","pm":["肱三头肌"],"sm":[],"s":["双手对握哑铃，膝微屈，背部挺直屈髋前俯至躯干接近水平，抬头","大臂贴身与地面平行，前臂下垂，肘部成90度","大臂固定，呼气，肱三头肌发力向后伸直手臂","顶峰稍停，吸气缓慢还原"],"slot":"upper","m":"tri","reps":"10-15"},
{"id":"Triceps_Pushdown_-_Rope_Attachment","name":"绳索下压（绳索把手）","en":"Triceps Pushdown - Rope Attachment","cats":["tri"],"eq":["cable"],"pe":"cable","lv":"beginner","pm":["肱三头肌"],"sm":[],"s":["高位滑轮挂绳索把手，对握","身体直立略前倾，大臂贴身垂直地面，前臂向上","呼气，大臂固定，下压同时将绳两端分开至大腿两侧，手臂伸直","顶峰停顿1秒，吸气缓慢还原"],"slot":"upper","m":"tri","reps":"10-15"},
{"id":"Underhand_Cable_Pulldowns","name":"反握高位下拉","en":"Underhand Cable Pulldowns","cats":["back"],"eq":["cable"],"pe":"cable","lv":"beginner","pm":["背阔肌"],"sm":["肱二头肌","中背","肩"],"s":["坐上下拉器械，调整膝垫高度固定身体","反握横杆，握距窄于肩","躯干后仰约30度，下背微弓、挺胸","呼气，沉肩后拉，将杆拉至上胸，肘部贴近身体，顶峰挤压背部","稍停后吸气缓慢还原至背阔肌完全伸展"],"slot":"pull","m":"vert","reps":"8-12"},
{"id":"Upright_Barbell_Row","name":"杠铃直立划船","en":"Upright Barbell Row","cats":["shoulder"],"eq":["barbell"],"pe":"barbell","lv":"beginner","pm":["肩"],"sm":["斜方肌"],"s":["正握杠铃，握距略窄于肩，杠铃贴于大腿前侧，肘微屈，背部挺直","呼气，三角肌中束发力，肘部引领向上外侧提起，杠铃贴身","提至接近下巴，肘始终高于前臂，躯干不动，顶端稍停","吸气，缓慢下放回起始位置"],"slot":"upper","m":"side","reps":"8-12"},
{"id":"V-Bar_Pulldown","name":"V把高位下拉","en":"V-Bar Pulldown","cats":["back"],"eq":["cable"],"pe":"cable","lv":"intermediate","pm":["背阔肌"],"sm":["肱二头肌","中背","肩"],"s":["坐上下拉器械，高位滑轮挂V形把手，调整膝垫固定身体","对握V把，挺胸，身体后仰约30度以更好激活背阔肌","呼气，背阔肌发力下拉，夹紧肩胛，至胸部接近把手，躯干不动","顶峰停顿1秒，吸气缓慢还原"],"slot":"pull","m":"vert","reps":"8-12"},
{"id":"Wide_Stance_Barbell_Squat","name":"宽距杠铃深蹲","en":"Wide Stance Barbell Squat","cats":["leg"],"eq":["barbell"],"pe":"barbell","lv":"intermediate","pm":["股四头肌"],"sm":["小腿","臀","腘绳肌","下背"],"s":["为安全起见在深蹲架内进行，杠铃置于斜方肌上，伸腿挺身出架","后退，站距宽于肩、脚尖略外展，抬头、背部挺直","吸气屈膝下蹲至大腿略低于平行，膝盖不宜过度超过脚尖","呼气，脚跟蹬地伸腿站起"],"slot":"lower","m":"quad","reps":"8-12"}
